// remux simply copies packets from input to output, adjusting timestamps.
func remux(octx *astiav.FormatContext, ictx *astiav.FormatContext, ostream *astiav.Stream, istream *astiav.Stream, ptsOffset int64) error {
	pkt := astiav.AllocPacket()
	defer pkt.Free()

	for {
		err := ictx.ReadFrame(pkt)
		if errors.Is(err, astiav.ErrEof) {
			break
		} else if err != nil {
			return fmt.Errorf("reading frame failed: %w", err)
		}

		if pkt.StreamIndex() == istream.Index() {
			pkt.RescaleTs(istream.TimeBase(), ostream.TimeBase())
			pkt.SetPts(pkt.Pts() + ptsOffset)
			pkt.SetDts(pkt.Dts() + ptsOffset)
			pkt.SetStreamIndex(ostream.Index())
			pkt.SetPos(-1)

			if err = octx.WriteInterleavedFrame(pkt); err != nil {
				log.Printf("Warning: writing frame failed: %v\n", err)
			}
		}
		pkt.Unref()
	}
	return nil
}

// transcodeAndMux decodes, filters, re-encodes, and muxes an incompatible stream.
func transcodeAndMux(octx *astiav.FormatContext, ostream *astiav.Stream, ictx *astiav.FormatContext, istream *astiav.Stream, ptsOffset int64) error {
	// Setup Decoder
	dec, err := astiav.FindDecoder(istream.CodecParameters().CodecID())
	if err != nil || dec == nil {
		return fmt.Errorf("finding decoder failed: %w", err)
	}
	decCtx := astiav.AllocCodecContext(dec)
	if decCtx == nil {
		return errors.New("allocating decoder context failed")
	}
	defer decCtx.Free()
	if err = istream.CodecParameters().ToCodecContext(decCtx); err != nil {
		return fmt.Errorf("copying decoder parameters failed: %w", err)
	}
	if err = decCtx.Open(dec, nil); err != nil {
		return fmt.Errorf("opening decoder context failed: %w", err)
	}

	// Setup Encoder
	enc, err := astiav.FindEncoder(ostream.CodecParameters().CodecID())
	if err != nil || enc == nil {
		return fmt.Errorf("finding encoder failed: %w", err)
	}
	encCtx := astiav.AllocCodecContext(enc)
	if encCtx == nil {
		return errors.New("allocating encoder context failed")
	}
	defer encCtx.Free()
	encCtx.SetSampleRate(ostream.CodecParameters().SampleRate())
	encCtx.SetSampleFmt(ostream.CodecParameters().SampleFormat())
	encCtx.SetChannelLayout(ostream.CodecParameters().ChannelLayout())
	encCtx.SetTimeBase(ostream.TimeBase())
	if err = encCtx.Open(enc, nil); err != nil {
		return fmt.Errorf("opening encoder context failed: %w", err)
	}

	// Setup Filter Graph
	filterGraph := astiav.AllocFilterGraph()
	if filterGraph == nil {
		return errors.New("allocating filter graph failed")
	}
	defer filterGraph.Free()

	filterStr := fmt.Sprintf("aresample=%d,aformat=sample_fmts=%s:channel_layouts=%s",
		encCtx.SampleRate(), encCtx.SampleFmt().Name(), encCtx.ChannelLayout().String())
	log.Printf("Using filter graph: %s", filterStr)

	if err = filterGraph.Parse(filterStr, istream.CodecParameters(), ostream.CodecParameters()); err != nil {
		return fmt.Errorf("parsing filter graph failed: %w", err)
	}
	if err = filterGraph.Configure(); err != nil {
		return fmt.Errorf("configuring filter graph failed: %w", err)
	}

	// Processing loop
	inPkt := astiav.AllocPacket()
	defer inPkt.Free()
	decodedFrame := astiav.AllocFrame()
	defer decodedFrame.Free()
	filteredFrame := astiav.AllocFrame()
	defer filteredFrame.Free()

	for {
		err = ictx.ReadFrame(inPkt)
		if err != nil && !errors.Is(err, astiav.ErrEof) {
			return fmt.Errorf("reading frame failed: %w", err)
		}

		if err == nil && inPkt.StreamIndex() != istream.Index() {
			inPkt.Unref()
			continue
		}

		// Send packet to decoder
		if err = decCtx.SendPacket(inPkt); err != nil {
			return fmt.Errorf("sending packet to decoder failed: %w", err)
		}
		inPkt.Unref()

		for {
			// Receive frame from decoder
			err = decCtx.ReceiveFrame(decodedFrame)
			if err != nil && !errors.Is(err, astiav.ErrEagain) && !errors.Is(err, astiav.ErrEof) {
				return fmt.Errorf("receiving frame from decoder failed: %w", err)
			}
			if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
				break
			}

			// Send frame to filter graph
			if err = filterGraph.Buffersrc().AddFrame(decodedFrame, astiav.NewBuffersrcFlags()); err != nil {
				return fmt.Errorf("adding frame to filter graph failed: %w", err)
			}
			decodedFrame.Unref()

			for {
				// Receive frame from filter graph
				err = filterGraph.Buffersink().GetFrame(filteredFrame, astiav.NewBuffersinkFlags()); err != nil {
					if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
						break
					}
					return fmt.Errorf("getting frame from filter graph failed: %w", err)
				}

				// Send frame to encoder
				if err = encCtx.SendFrame(filteredFrame); err != nil {
					return fmt.Errorf("sending frame to encoder failed: %w", err)
				}
				filteredFrame.Unref()

				for {
					// Receive packet from encoder
					outPkt := astiav.AllocPacket()
					err = encCtx.ReceivePacket(outPkt)
					if errors.Is(err, astiav.ErrEagain) || errors.Is(err, astiav.ErrEof) {
						outPkt.Free()
						break
					} else if err != nil {
						outPkt.Free()
						return fmt.Errorf("receiving packet from encoder failed: %w", err)
					}

					// Apply offset and write packet
					outPkt.RescaleTs(encCtx.TimeBase(), ostream.TimeBase())
					outPkt.SetPts(outPkt.Pts() + ptsOffset)
					outPkt.SetDts(outPkt.Dts() + ptsOffset)
					outPkt.SetStreamIndex(ostream.Index())
					outPkt.SetPos(-1)

					if err = octx.WriteInterleavedFrame(outPkt); err != nil {
						log.Printf("Warning: writing frame failed: %v\n", err)
					}
					outPkt.Free() // Free here since we are in a loop
				}
			}
		}
		if errors.Is(err, astiav.ErrEof) {
			break
		}
	}
	return nil
}

